def df_to_nested_dict(df):
    result = {}
    for _, row in df.iterrows():
        current_dict = result
        for col in df.columns:
            current_dict = {k: {v: v2 if v == col else v3 for k, v2, v3 in zip(current_dict.keys(), row[col], row[col + 1])}
                            if col + 1 in df.columns else {k: v2 for k, v2 in zip(current_dict.keys(), row[col])}
                            if col in df.columns else current_dict}
        result = current_dict
    return result

