    key_value_pairs = {}
    for pair in message.split(', '):
        key, value = pair.strip().split(': ')
        key_value_pairs[key] = value
    return key_value_pairs

def process_message(message):
    try:
        key_value_pairs = extract_key_value_pairs(message)
        return pd.Series(key_value_pairs)
    except Exception as e:
        print(f"Error processing message: {e}")
        return pd.Series()

def expand_message_to_dataframe(df):
    expanded_df = df.copy()
    for index, row in df.iterrows():
        message = row['message']
        processed_message = process_message(message)
        if processed_message.empty:
            continue
        expanded_df = expanded_df.join(processed_message.rename('message'), on=0)
        expanded_df = expanded_df.drop(columns=['message'])
